let currentLang = 'zh-CN';
let _i18nObserver = null;

function initI18n(lang) {
    if (!lang) lang = 'zh-CN';
    if (!I18N_DICT[lang]) lang = 'zh-CN';
    currentLang = lang;
    
    if (lang === 'zh-CN') {
        if (_i18nObserver) _i18nObserver.disconnect();
        return;
    }
    
    translateDOM(document.body);
    
    if (_i18nObserver) _i18nObserver.disconnect();
    _i18nObserver = new MutationObserver(mutations => {
        mutations.forEach(m => {
            if (m.type === 'childList') {
                m.addedNodes.forEach(n => translateDOM(n));
            } else if (m.type === 'characterData') {
                translateDOM(m.target);
            }
        });
    });
    _i18nObserver.observe(document.body, { childList: true, subtree: true, characterData: true });
}

function translateDOM(node) {
    if (!node) return;
    const dict = I18N_DICT[currentLang];
    if (!dict) return;
    
    if (node.nodeType === Node.TEXT_NODE) {
        let text = node.nodeValue;
        if (!text || !text.trim()) return;
        
        let original = text.trim();
        // Exact match
        if (dict[original]) {
            node.nodeValue = text.replace(original, dict[original]);
            return;
        }
        // Avoid partial matching to prevent obvious translation errors like replacing '的' everywhere
    } else if (node.nodeType === Node.ELEMENT_NODE) {
        if (node.tagName === 'INPUT' || node.tagName === 'TEXTAREA') {
            let p = node.getAttribute('placeholder');
            if (p) {
                let origP = p.trim();
                if (dict[origP]) node.setAttribute('placeholder', dict[origP]);
            }
            let v = node.getAttribute('value');
            if (v && node.type === 'button') {
                let origV = v.trim();
                if (dict[origV]) node.setAttribute('value', dict[origV]);
            }
        }
        if (node.tagName === 'SCRIPT' || node.tagName === 'STYLE' || node.tagName === 'CODE') return;
        
        for (let i = 0; i < node.childNodes.length; i++) {
            translateDOM(node.childNodes[i]);
        }
    }
}
